mapper.update:
UPDATE FIN_CASH_INFO SET 
	CCY = #{ccy},FINPROD_ID = #{finprodId}
WHERE CASH_ID = #{cashId}

UPDATE FIN_RATE_INFO SET 

		COEFFICIENT=#{coefficient},SPREAD_RATE=#{spreadRate},RATE=#{currentRate},

	RATE=#{rate},


	INT_TYPE=#{rateType},EFF_DATE = #{effDate}
WHERE CASH_ID = #{cashId} AND EFF_DATE = #{oldEffDate}

UPDATE FIN_CASH_CALC_RULE SET
	CALC_TYPE=#{rateType},YIELD=#{yield},EFF_DATE = #{effDate},BASIS=#{basis}
WHERE CASH_ID = #{cashId} AND EFF_DATE = #{oldEffDate}

mapper.select:
SELECT T1.INT_RATE
FROM  MST_INT_RATE_INFO T1
WHERE T1.INT_RATE_ID = #{indexId}
AND T1.CCY = #{ccy}
AND T1.EFF_DATE = (SELECT MAX(T2.EFF_DATE) FROM MST_INT_RATE_INFO T2 WHERE T2.INT_RATE_ID = #{indexId} AND T2.CCY = #{ccy} AND T2.EFF_DATE <= TO_DATE(#{effDate},'YYYY-MM-DD'))

select count(1)
from FIN_CASH_INFO fci
inner join 
FIN_CASH_CALC_RULE fccr on fci.CASH_ID = fccr.CASH_ID
where
fci.CCY = #{ccy}
and fccr.EFF_DATE = #{effDate}
and fci.CASH_TYPE_1 = #{CASH_TYPE_1_02}
and fci.CASH_TYPE_2 = #{CASH_TYPE_2_C02}
and fci.FINPROD_ID = #{busiAcctNo}
and fci.CASH_ID = #{cashId}
